using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize]
public class ShipmentsController : ControllerBase
{
    private readonly ApplicationDbContext _db;

    public ShipmentsController(ApplicationDbContext db)
    {
        _db = db;
    }

    [HttpGet]
    [Authorize(Roles = "Dispatcher")]
    public async Task<ActionResult<List<Shipment>>> GetAll()
    {
        var entities = await _db.Shipments.ToListAsync();
        return entities.Select(MapToDto).ToList();
    }

    [HttpGet("track/{trackingNumber}")]
    public async Task<ActionResult<Shipment>> Track(string trackingNumber)
    {
        var entity = await _db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        if (entity is null)
            return NotFound();
        return MapToDto(entity);
    }

    [HttpPut("{id}")]
    [Authorize(Roles = "Dispatcher")]
    public async Task<ActionResult<Shipment>> Update(int id, Shipment shipment)
    {
        var entity = await _db.Shipments.FindAsync(id);
        if (entity is null)
            return NotFound();

        entity.Status = (int)shipment.Status;
        entity.Origin = shipment.Origin;
        entity.Destination = shipment.Destination;
        entity.EstimatedDelivery = shipment.EstimatedDelivery;
        entity.CustomerEmail = shipment.CustomerEmail;
        entity.Description = shipment.Description;

        await _db.SaveChangesAsync();
        return MapToDto(entity);
    }

    [HttpPost]
    [Authorize(Roles = "Dispatcher")]
    public async Task<ActionResult<Shipment>> Create(Shipment shipment)
    {
        var entity = new ShipmentEntity
        {
            TrackingNumber = shipment.TrackingNumber,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = (int)shipment.Status,
            CreatedDate = DateTime.UtcNow,
            EstimatedDelivery = shipment.EstimatedDelivery,
            CustomerEmail = shipment.CustomerEmail,
            Description = shipment.Description
        };

        _db.Shipments.Add(entity);
        await _db.SaveChangesAsync();
        return CreatedAtAction(nameof(Track), new { trackingNumber = entity.TrackingNumber }, MapToDto(entity));
    }

    private static Shipment MapToDto(ShipmentEntity e) => new()
    {
        Id = e.Id,
        TrackingNumber = e.TrackingNumber,
        Origin = e.Origin,
        Destination = e.Destination,
        Status = (ShipmentStatus)e.Status,
        CreatedDate = e.CreatedDate,
        EstimatedDelivery = e.EstimatedDelivery,
        CustomerEmail = e.CustomerEmail,
        Description = e.Description
    };
}

