+@rendermode InteractiveAuto
+@inject IShipmentService ShipmentService
+
+<PageTitle>Dispatcher Dashboard</PageTitle>
+
+<h2>📋 Dispatcher Dashboard</h2>
+
+@if (errorMessage is not null)
+{
+    <div class="alert alert-danger mt-3">@errorMessage</div>
+}
+
+<div class="row mt-3 mb-3">
+    <div class="col-md-3">
+        <label class="form-label">Filter by Status</label>
+        <select class="form-select" @bind="statusFilter">
+            <option value="">All</option>
+            @foreach (var s in Enum.GetValues<ShipmentStatus>())
+            {
+                <option value="@s">@s</option>
+            }
+        </select>
+    </div>
+    <div class="col-md-3 d-flex align-items-end">
+        <button class="btn btn-success" @onclick="ToggleCreateForm">
+            @(showCreateForm ? "Cancel" : "+ New Shipment")
+        </button>
+    </div>
+</div>
+
+@if (showCreateForm)
+{
+    <div class="card mb-4">
+        <div class="card-header">Create New Shipment</div>
+        <div class="card-body">
+            <div class="row g-3">
+                <div class="col-md-4">
+                    <label class="form-label">Tracking Number</label>
+                    <input class="form-control" @bind="newShipment.TrackingNumber" />
+                </div>
+                <div class="col-md-4">
+                    <label class="form-label">Origin</label>
+                    <input class="form-control" @bind="newShipment.Origin" />
+                </div>
+                <div class="col-md-4">
+                    <label class="form-label">Destination</label>
+                    <input class="form-control" @bind="newShipment.Destination" />
+                </div>
+                <div class="col-md-4">
+                    <label class="form-label">Customer Email</label>
+                    <input class="form-control" @bind="newShipment.CustomerEmail" />
+                </div>
+                <div class="col-md-4">
+                    <label class="form-label">Estimated Delivery</label>
+                    <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
+                </div>
+                <div class="col-md-4">
+                    <label class="form-label">Description</label>
+                    <input class="form-control" @bind="newShipment.Description" />
+                </div>
+                <div class="col-12">
+                    <button class="btn btn-primary" @onclick="CreateShipment">Create</button>
+                </div>
+            </div>
+        </div>
+    </div>
+}
+
+@if (shipments is null)
+{
+    <p><em>Loading shipments...</em></p>
+}
+else
+{
+    <div class="table-responsive">
+        <table class="table table-striped table-hover">
+            <thead class="table-dark">
+                <tr>
+                    <th>Tracking #</th>
+                    <th>Origin</th>
+                    <th>Destination</th>
+                    <th>Status</th>
+                    <th>Customer</th>
+                    <th>Est. Delivery</th>
+                    <th>Actions</th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var s in FilteredShipments)
+                {
+                    <tr>
+                        <td>@s.TrackingNumber</td>
+                        <td>@s.Origin</td>
+                        <td>@s.Destination</td>
+                        <td>
+                            @if (editingId == s.Id)
+                            {
+                                <select class="form-select form-select-sm" @bind="editStatus">
+                                    @foreach (var st in Enum.GetValues<ShipmentStatus>())
+                                    {
+                                        <option value="@st">@st</option>
+                                    }
+                                </select>
+                            }
+                            else
+                            {
+                                <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
+                            }
+                        </td>
+                        <td>@s.CustomerEmail</td>
+                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "N/A")</td>
+                        <td>
+                            @if (editingId == s.Id)
+                            {
+                                <button class="btn btn-sm btn-success me-1" @onclick="() => SaveStatus(s)">Save</button>
+                                <button class="btn btn-sm btn-secondary" @onclick="CancelEdit">Cancel</button>
+                            }
+                            else
+                            {
+                                <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(s)">Update Status</button>
+                            }
+                        </td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    </div>
+}
+
+@code {
+    private List<Shipment>? shipments;
+    private string? errorMessage;
+    private string statusFilter = "";
+    private bool showCreateForm;
+    private Shipment newShipment = new();
+    private int? editingId;
+    private ShipmentStatus editStatus;
+
+    private IEnumerable<Shipment> FilteredShipments =>
+        string.IsNullOrEmpty(statusFilter)
+            ? shipments!
+            : shipments!.Where(s => s.Status.ToString() == statusFilter);
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadShipments();
+    }
+
+    private async Task LoadShipments()
+    {
+        try
+        {
+            shipments = await ShipmentService.GetAllShipmentsAsync();
+        }
+        catch
+        {
+            errorMessage = "Failed to load shipments.";
+            shipments = new();
+        }
+    }
+
+    private void ToggleCreateForm() => showCreateForm = !showCreateForm;
+
+    private async Task CreateShipment()
+    {
+        try
+        {
+            await ShipmentService.CreateShipmentAsync(newShipment);
+            newShipment = new();
+            showCreateForm = false;
+            await LoadShipments();
+        }
+        catch
+        {
+            errorMessage = "Failed to create shipment.";
+        }
+    }
+
+    private void StartEdit(Shipment s)
+    {
+        editingId = s.Id;
+        editStatus = s.Status;
+    }
+
+    private void CancelEdit() => editingId = null;
+
+    private async Task SaveStatus(Shipment s)
+    {
+        try
+        {
+            s.Status = editStatus;
+            await ShipmentService.UpdateShipmentAsync(s);
+            editingId = null;
+            await LoadShipments();
+        }
+        catch
+        {
+            errorMessage = "Failed to update shipment status.";
+        }
+    }
+
+    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info text-dark",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Cancelled => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
+

