1. using Microsoft.AspNetCore.Authorization;
2. using Microsoft.AspNetCore.Mvc;
3. using Microsoft.EntityFrameworkCore;
4. using ShipmentTracker.Client.Models;
5. using ShipmentTracker.Data;
6. 
7. namespace ShipmentTracker.Controllers;
8. 
9. [ApiController]
10. [Route("api/[controller]")]
11. [Authorize]
12. public class ShipmentsController : ControllerBase
13. {
14.     private readonly ApplicationDbContext _db;
15. 
16.     public ShipmentsController(ApplicationDbContext db)
17.     {
18.         _db = db;
19.     }
20. 
21.     [HttpGet]
22.     [Authorize(Roles = "Dispatcher")]
23.     public async Task<ActionResult<List<Shipment>>> GetAll()
24.     {
25.         var entities = await _db.Shipments.ToListAsync();
26.         return entities.Select(MapToDto).ToList();
27.     }
28. 
29.     [HttpGet("track/{trackingNumber}")]
30.     public async Task<ActionResult<Shipment>> Track(string trackingNumber)
31.     {
32.         var entity = await _db.Shipments
33.             .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
34.         if (entity is null)
35.             return NotFound();
36.         return MapToDto(entity);
37.     }
38. 
39.     [HttpPut("{id}")]
40.     [Authorize(Roles = "Dispatcher")]
41.     public async Task<ActionResult<Shipment>> Update(int id, Shipment shipment)
42.     {
43.         var entity = await _db.Shipments.FindAsync(id);
44.         if (entity is null)
45.             return NotFound();
46. 
47.         entity.Status = (int)shipment.Status;
48.         entity.Origin = shipment.Origin;
49.         entity.Destination = shipment.Destination;
50.         entity.EstimatedDelivery = shipment.EstimatedDelivery;
51.         entity.CustomerEmail = shipment.CustomerEmail;
52.         entity.Description = shipment.Description;
53. 
54.         await _db.SaveChangesAsync();
55.         return MapToDto(entity);
56.     }
57. 
58.     [HttpPost]
59.     [Authorize(Roles = "Dispatcher")]
60.     public async Task<ActionResult<Shipment>> Create(Shipment shipment)
61.     {
62.         var entity = new ShipmentEntity
63.         {
